'use strict';

// 中转文本模型目录：DashScope compatible-mode（OpenAI 兼容 chat）。
// 仅允许长期别名白名单，禁止任意模型名透传。

const { TEXT_ALLOWED } = require('@aigc-desk/contracts');

const CHAT_MODELS = Object.freeze(TEXT_ALLOWED);

function isChatModel(model) {
  return typeof model === 'string' && CHAT_MODELS.includes(model);
}

module.exports = { CHAT_MODELS, isChatModel };
